-- 130: tokens of appreciation in the guides (docs/TOKEN_POLICY.md, migrations 127-129), in English, Italian and Urdu.
-- Generated by Documentazione/guide-help/build-tokens.mjs from tokens.mjs. No figures: rates and milestones are set in
-- the Reward department's page.
--
-- Each guide gets one block, put before its last button (or at the end when it has none). The rest of the guide is
-- left as it is, so changes made in the app since are kept. A guide that already has the block (data-v="tokens") is
-- left alone, so this is safe to run again. The Urdu guides stay drafts (help_pages.draft is not touched).
-- Run this BEFORE merging the PR.

begin;

create or replace function pg_temp.add_tokens_block(p_slug text, p_block text)
returns void
language plpgsql
as $$
declare
  n constant text := '<p><a class="btn"';
  r int;
begin
  update public.help_pages h
     set html_content = case
           when strpos(h.html_content, n) > 0 then
             -- r is where the last button starts, counted from the end.
             left(h.html_content, length(h.html_content) - strpos(reverse(h.html_content), reverse(n)) - length(n) + 1)
             || p_block || E'\n'
             || right(h.html_content, strpos(reverse(h.html_content), reverse(n)) + length(n) - 1)
           else rtrim(h.html_content) || E'\n' || p_block
         end,
         updated_at = now(),
         updated_by_email = 'migration 130'
   where h.slug = p_slug
     and h.html_content not like '%data-v="tokens"%';
end;
$$;

select pg_temp.add_tokens_block('find-read_en', $help_tokens$<details data-v="tokens"><summary>Tokens of appreciation</summary>
<p>When you are signed in, <b>My Space</b> also shows your <b>Tokens of appreciation</b>: a thank-you for what you give the archive outside tasks, such as a text you proposed or a reading of yours. They are never money. You see what you gave, how many times your texts were opened and your readings listened to (counted anonymously, never by person), and your certificates, which you can <b>Print</b>.</p>
<p>There you also choose whether to be thanked by name in the monthly thanks, in the app and in Hayat. You can withdraw it at any time. Those under 18 are thanked privately, in My Space.</p>
</details>$help_tokens$);
select pg_temp.add_tokens_block('find-read_it', $help_tokens$<details data-v="tokens"><summary>Tokens of appreciation</summary>
