select pg_temp.add_tokens_block('propose_ur', $help_tokens$<details data-v="tokens"><summary>Tokens of appreciation</summary>
<p>کریڈٹ ٹاسک کا معاوضہ ہیں؛ ٹوکن کسی تحفے کا شکریہ ہیں۔ جب آپ کی تجویز شائع ہوتی ہے تو آپ کو اس کے صفحات کے حساب سے ٹوکن ملتے ہیں، اور آڈیو یا ویڈیو کے لیے اس کے منٹوں کے حساب سے۔ یہ خود بخود ملتے ہیں اور کبھی پیسے نہیں ہوتے۔ ٹوکن شروع ہونے سے پہلے شائع ہونے والی تجاویز بھی گنی جاتی ہیں۔ آپ انہیں <b>My Space</b> میں دیکھتے ہیں، اور یہ بھی کہ آپ کا متن کتنی بار کھولا گیا۔</p>
<p>اگر آپ تجاویز منظور کرتے ہیں تو دیکھیں کہ صفحات یا منٹ درج ہوں: ٹوکن انہی سے گنے جاتے ہیں۔ اگر کوئی شائع شدہ تجویز آرکائیو میں پہلے سے موجود کسی متن کی نقل نکلے تو Reward کو بتائیں۔ صرف Reward ہی، ایک نوٹ کے ساتھ، ٹوکن منسوخ کرتا ہے۔</p>
</details>$help_tokens$);
